    private void forgetKnownRule(String description, String existingFileName) {
        if (existingFileName == null) {
            return;
        }

        IntegrityInspection current = inspectEntryWithoutName(description, existingFileName);
        boolean shared = hasAnotherEntrySharing(description, current);
        storedRules.removePropertyWithoutSync(description);
        if (!shared && !current.broken && current.resolvedPath != null) {
            deleteEntryFile(current);
        }
        storedRules.syncFileSystem();
    }

    private boolean hasAnotherEntrySharing(String description, IntegrityInspection current) {
        for (Map.Entry<String, String> entry : storedRules.snapshot().entrySet()) {
            if (entry.getKey().equals(description)) {
                continue;
            }
            if (entry.getValue().equals(current.recordedName)) {
                return true;
            }
            IntegrityInspection other = inspectEntryWithoutName(entry.getKey(), entry.getValue());
            if (current.resolvedPath != null && other.resolvedPath != null && sameFile(current.resolvedPath, other.resolvedPath)) {
                return true;
            }
        }
        return false;
    }

    private Path validateSaveTarget(String fileName, boolean existingEntry) {
        Path path = pathFor(fileName);
        if (!isDirectFileName(fileName, path) || STORED_RULES_FILE_NAME.equals(fileName)) {
            throw new StoreUpdateFailedException(String.format("Refusing to write violation file '%s' outside the store's file namespace", fileName));
        }

        boolean exists = Files.exists(path, LinkOption.NOFOLLOW_LINKS);
        if (!existingEntry) {
            if (exists || storedRules.snapshot().values().stream().anyMatch(fileName::equals)) {
                throw new StoreUpdateFailedException(String.format("Refusing to overwrite occupied violation file '%s'", fileName));
            }
            return path;
        }

        if (exists) {
            Path resolved = resolveExistingPath(path);
            if (resolved == null || !isRegularDirectFile(resolved) || resolved.equals(storedRulesPath())) {
                throw new StoreUpdateFailedException(String.format("Refusing to write invalid violation file '%s'", fileName));
            }
        }
        return path;
    }

    private void write(List<String> violations, Path ruleDetails) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        try {
            Files.write(ruleDetails, builder.toString().getBytes(UTF_8));
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
