        String candidate;
        try {
            candidate = ruleViolationFileNameStrategy.createRuleFileName(ruleDescription);
        } catch (RuntimeException e) {
            if (duringInitialization) {
                throw new StoreInitializationFailedException(String.format(
                        "Could not derive a violation file name for rule '%s'", ruleDescription), e);
            }
            throw e;
        }
        if (candidate == null || candidate.trim().isEmpty()) {
            String message = String.format("RuleViolationFileNameStrategy yielded no file name for rule '%s'", ruleDescription);
