    private IntegrityReport inspectIntegrity() {
        Map<String, String> entries = storedRules.snapshot();
        List<IntegrityInspection> inspections = new ArrayList<>();
        for (Map.Entry<String, String> entry : entries.entrySet()) {
            inspections.add(inspectEntry(entry.getKey(), entry.getValue()));
        }


        Map<String, List<IntegrityInspection>> byRecordedName = groupBy(inspections, inspection -> inspection.recordedName);
        Map<String, List<IntegrityInspection>> byDerivedName = groupBy(inspections,
                inspection -> inspection.derivedName == null ? null : inspection.derivedName);
        Map<String, List<IntegrityInspection>> byResolvedFile = new HashMap<>();
        for (IntegrityInspection inspection : inspections) {
            if (inspection.resolvedPath != null) {
                byResolvedFile.computeIfAbsent(fileIdentity(inspection.resolvedPath), __ -> new ArrayList<>()).add(inspection);
            }
        }

        for (IntegrityInspection inspection : inspections) {
            inspection.shared = byRecordedName.get(inspection.recordedName).size() > 1;
            if (inspection.resolvedPath != null) {
                inspection.shared |= byResolvedFile.get(fileIdentity(inspection.resolvedPath)).size() > 1;
            }
            inspection.colliding = inspection.derivedName != null
                    && byDerivedName.get(inspection.derivedName).size() > 1;
            inspection.misplaced = inspection.derivedName != null
                    && !inspection.recordedName.equals(inspection.derivedName);
            inspection.occupied = isOccupied(inspection, inspections);
        }

        List<String> unownedFiles = findUnownedFiles(inspections);
        return new IntegrityReport(inspections, unownedFiles);
    }

    private IntegrityInspection inspectEntry(String description, String recordedName) {
        String derivedName = namesCanBeDerived ? createRuleFileName(description, true) : null;
        IntegrityInspection result = inspectEntryWithoutName(description, recordedName);
        result.derivedName = derivedName;
        if (!result.broken && result.resolvedPath != null) {
